//! Build recipe/layout commands; generated bytes render before destination mutation.
use std::{fs, path::PathBuf};
use vibeos_codegen::{baseaddress, cflags};
pub const NAMES: &[&str] = &["cflags", "baseaddress"];

pub fn run(raw: Vec<String>) -> Result<u8, String> {
    let mut root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    let (mut name, mut output, mut dir) = (None, None, None);
    let (mut check, mut stdout, mut wide) = (false, false, false);
    let (mut arches, mut targets, mut inputs) = (Vec::new(), Vec::new(), Vec::new());
    let expanded = raw
        .into_iter()
        .flat_map(|s| {
            if s.starts_with("--") && s.contains('=') {
                let (k, v) = s.split_once('=').unwrap();
                vec![k.to_owned(), v.to_owned()]
            } else {
                vec![s]
            }
        })
        .collect::<Vec<_>>();
    let mut args = expanded.into_iter();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--root" => root = args.next().ok_or("--root requires DIR")?.into(),
            "--arch" => arches.push(args.next().ok_or("--arch requires ARCH")?),
            "--target" => targets.push(args.next().ok_or("--target requires NAME")?),
            "--output" | "-o" => {
                output = Some(PathBuf::from(args.next().ok_or("--output requires FILE")?))
            }
            "--output-dir" => {
                dir = Some(PathBuf::from(
                    args.next().ok_or("--output-dir requires DIR")?,
                ))
            }
            "--check" => check = true,
            "--stdout" => stdout = true,
            "-64" | "--64" => wide = true,
            s if NAMES.contains(&s) && name.is_none() => name = Some(arg),
            s if !s.starts_with('-') => inputs.push(PathBuf::from(arg)),
            _ => return Err(format!("unexpected build generator argument: {arg}")),
        }
    }
    if check && stdout {
        return Err("--check and --stdout are mutually exclusive".into());
    }
    if output.is_some() && dir.is_some() {
        return Err("choose --output or --output-dir".into());
    }
    let name = name.ok_or("missing build generator")?;
    let mut rendered = Vec::new();
    if name == "cflags" {
        if !inputs.is_empty() || wide || dir.is_some() {
            return Err("cflags accepts --arch, --target and --output".into());
        }
        if arches.is_empty() {
            return Err("cflags requires --arch".into());
        }
        if targets.is_empty() {
            targets.push("genincdata".to_owned());
        }
        if (stdout || output.is_some()) && arches.len() * targets.len() != 1 {
            return Err("--stdout/--output requires one architecture and target".into());
        }
        for target in targets {
            for arch in &arches {
                if !matches!(arch.as_str(), "i386" | "amd64" | "arm64") {
                    return Err(format!("unsupported architecture: {arch}"));
                }
                let content = cflags::generate(&root, arch, &target)?;
                if stdout {
                    println!(
                        "{}",
                        serde_json::to_string(&content).map_err(|e| e.to_string())?
                    );
                    return Ok(0);
                }
                let content = content.ok_or_else(|| format!("[{target} {arch}] no compile database or target entries; configure this checkout first"))?;
                let path = output.clone().unwrap_or_else(|| {
                    root.join(format!(
                        "sdk/lib/rust/reactos-link/cflags/{target}.{arch}.flags"
                    ))
                });
                rendered.push((path, content));
            }
        }
    } else {
        if !arches.is_empty() || !targets.is_empty() {
            return Err("baseaddress accepts directory inputs and -64".into());
        }
        if inputs.is_empty() {
            return Err("baseaddress requires an input directory".into());
        }
        if (stdout || output.is_some()) && inputs.len() != 1 {
            return Err("--stdout/--output requires one input directory".into());
        }
        for input in inputs {
            let generated = baseaddress::generate(&input, wide)?;
            for warning in generated.missing {
                eprintln!("# {warning}");
            }
            if stdout {
                print!("{}", generated.content);
                return Ok(0);
            }
            let path = output.clone().unwrap_or_else(|| {
                dir.as_ref()
                    .map(|d| d.join(generated.target_file))
                    .unwrap_or_else(|| root.join("sdk/cmake").join(generated.target_file))
            });
            rendered.push((path, generated.content));
        }
    }
    let mut stale = false;
    for (i, (path, content)) in rendered.iter().enumerate() {
        if check {
            if fs::read(path).ok().as_deref() != Some(content.as_bytes()) {
                stale = true;
                eprintln!("DRIFT: {}", path.display());
            }
        } else {
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            }
            crate::write_atomic(path, content.as_bytes(), i)?;
        }
    }
    Ok(u8::from(stale))
}
